from __future__ import annotations
import html
import json
from probe_binding_viewer import HTML_TEMPLATE

QC_CSS=r'''
.qc-header{padding:20px;margin:18px 0}.qc-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:14px 0}.qc-kpi{background:#f4f7f8;border:1px solid #e1e8ed;border-radius:9px;padding:12px 14px}.qc-kpi strong{display:block;font-size:25px;line-height:1.25}.qc-kpi span{font-size:12px;color:#5e7180}.qc-tag{display:inline-block;border-radius:5px;font-size:10px;padding:3px 6px;font-weight:700;white-space:normal}.qc-tag.ok{background:#e8f3ec;color:#285e40}.qc-tag.review{background:#fff0d3;color:#835812}.qc-tag.pending{background:#e9edf1;color:#485c6d}.qc-controls{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.qc-controls label{font-size:12px}.qc-note{font-size:12px;line-height:1.6;color:#607180}.qc-scope{margin:14px 0 0;padding:12px 15px;background:#fff8e8;border-left:3px solid #d7a342;border-radius:5px}.qc-scope strong{color:#6b4b13}.qc-status-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px}.qc-status-item{border-bottom:1px solid #e1e8ed;padding:9px 0}.qc-status-item>strong{font-size:12px}.qc-inspector{border-top:1px solid #dce3e8;border-bottom:1px solid #dce3e8;padding:14px 0;margin:12px 0}.qc-inspector h3{margin:0 0 7px}.qc-inspector details{border-bottom:1px solid #e8edf0;padding:9px 0}.qc-inspector .facts{margin:10px 0}.qc-inspector pre{font-size:10px;overflow:auto;background:#f2f5f7;padding:8px;border-radius:5px}.qc-mini-table{font-size:11px;white-space:normal}.qc-mini-table td,.qc-mini-table th{padding:5px}.qc-partner{display:flex;align-items:center;gap:7px;margin:5px 0;flex-wrap:wrap}.qc-partner button{font-size:10px}.qc-scan-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.qc-load-error{color:#a23021;font-size:12px;white-space:pre-wrap}.qc-detail-scroll{max-height:280px;overflow:auto}.qc-legend{font-size:11px;padding:5px 0;color:#607180}.qc-missing{color:#755315;font-weight:650}.qc-inspector table td{overflow-wrap:anywhere}.qc-inspector .facts strong{font-size:18px}.inspector{max-height:calc(100vh - 35px);overflow:auto}.tablewrap{max-height:530px}.qc-pair-geometry{font:11px/1.7 ui-monospace,SFMono-Regular,Consolas,monospace;overflow:auto;padding:10px;background:#f3f6f8;white-space:pre;border-radius:5px}.qc-scope p{margin:3px 0}.qc-upload{display:none}
@media(max-width:880px){.qc-kpis{grid-template-columns:1fr 1fr}.qc-status-grid{grid-template-columns:1fr}.inspector{max-height:none}}
'''
QC_HEADER=r'''
<section class="card qc-header" aria-label="Integrated probe quality checks">
<div class="cardheading"><div><div class="eyebrow">QC WORKBENCH / INPUT-PRESERVING REVIEW</div><h2>Temperature, sequence specificity and interactions</h2></div><span class="qc-tag pending" id="qcCompletion">Partial QC</span></div>
<div id="qcKpis" class="qc-kpis"></div>
<div class="qc-controls">
<label>Temperature calculation <select id="qcProfile" aria-label="Temperature calculation profile"></select></label>
<label>Highlight on map <select id="qcColor"><option value="readout">Dp7 / Dp3 readout</option><option value="tm">Outside selected Tm window</option><option value="off">Possible off-target matches</option><option value="stem">Complementary-stem flags</option><option value="spacing">Possible flank-spacing issue</option></select></label>
</div>
<p class="qc-note" id="qcSettings"></p><p class="qc-legend" id="qcMapLegend"></p>
<div id="qcScope" class="qc-scope"></div>
<details style="margin-top:12px"><summary>Which checks actually ran? Show methods and missing references</summary><div id="qcStatus" class="qc-status-grid"></div><p class="qc-note" id="qcRefs"></p></details>
<div class="qc-scan-actions"><button id="exportQc">Export current QC table (CSV)</button><button id="loadQc">Load another QC result (JSON)</button><button id="saveQcHtml">Save this viewer (HTML)</button><button id="openRunHelp">How to run the complete checks</button><input class="qc-upload" id="qcFile" type="file" accept=".json,application/json"></div>
<p class="qc-load-error" id="qcLoadError"></p>
<details id="qcRunHelp"><summary>Run / reload instructions</summary><p>This page inspects saved results; it does not download a genome, run BLAST or run full folding in the browser. From the unzipped toolkit folder run:</p><pre class="sequence">python3 run_qc.py --out output_new</pre><p>To require full DNA folding after installing ViennaRNA:</p><pre class="sequence">python3 run_qc.py --folding vienna --out output_folded</pre><p>Add your installed human-genome BLAST database with <code>--blast-db hg38=/path/to/database</code>, and your construct with <code>--background construct=/path/to/construct.fasta</code>. Then open the new HTML or load its <code>binding_map.json</code> here. See HOW_TO_RUN.txt for complete commands and the allowed-target interval format. Probe design is a separate step; this program does not redesign or remove oligos.</p></details>
</section>
'''
QC_FILTER=r'''
<div class="toolrow"><label>QC filter <select id="qcFilter"><option value="all">All probes</option><option value="tm_in">Within selected Tm window</option><option value="tm_out">Outside selected Tm window</option><option value="off">Off-target match flags</option><option value="stem">Complementary-stem flags</option><option value="spacing">Flank-spacing flags</option></select></label><label>Sort <select id="qcSort"><option value="position">Position / name</option><option value="tm_hi">Tm: highest first</option><option value="tm_lo">Tm: lowest first</option><option value="off">Off-target count</option><option value="stem">Longest pair stem</option></select></label><label><input type="checkbox" id="qcDim" checked> Dim nonmatching probes on maps</label></div>
<p class="range-info">QC filters do not change the probe set. Map counts always include all loaded probes. Grey/missing is not a pass.</p>
'''
QC_JS=r'''
// Integrated QC extension. Calculation profiles change the view of precomputed
// values; they do not rerun thermodynamics or change any primary sequence.
const qstate={profile:DATA.qc.active_profile,filter:'all',sort:'position',color:'readout',dim:true};
const profileLabels={oligominer1_2nM:'OligoMiner-style / 2 nM + trace target',oligominer1_defaults:'OligoMiner source defaults / 25 + 25 nM',previous_NN_audit:'Earlier nearest-neighbor audit / 2 nM'};
const num=(v,n=2)=>v===null||v===undefined?'not run':Number(v).toFixed(n);
function tval(p){return p.qc.thermo[qstate.profile].adjusted_screen_C;}
function tmOk(p){return p.qc.thermo[qstate.profile].in_window;}
function stemFlag(p){return p.qc.exact_stem_review;}
function matchesQc(p){switch(qstate.filter){case 'tm_in':return tmOk(p);case 'tm_out':return !tmOk(p);case 'off':return p.qc.off_target_review_count>0;case 'stem':return stemFlag(p);case 'spacing':return p.qc.spacing_flags.length>0;default:return true;}}
function qcTag(text,kind='pending'){return `<span class="qc-tag ${kind}">${esc(text)}</span>`;}
function visibleProbes(){const query=$('searchInput').value.trim().toUpperCase(),ro=$('readoutFilter').value,repeated=$('repeatsOnly').checked;return DATA.probes.filter(p=>{const n=countHere(p.index,state.region);return n>0&&matchesQc(p)&&(!ro||p.readout===ro)&&(!repeated||n>1)&&(!query||p.name.toUpperCase().includes(query)||p.arm.includes(query));}).sort((a,b)=>{switch(qstate.sort){case 'tm_hi':return tval(b)-tval(a);case 'tm_lo':return tval(a)-tval(b);case 'off':return b.qc.off_target_review_count-a.qc.off_target_review_count;case 'stem':return b.qc.max_dimer_stem-a.qc.max_dimer_stem;default:return a.index-b.index;}});}
function qcTable(){const rows=visibleProbes();$('tableCount').textContent=`${rows.length} / ${refs.get(state.region).summary.unique_probe_rows} oligos`;
$('probeRows').innerHTML=rows.map(p=>{const q=p.qc;return `<tr data-probe="${p.index}" tabindex="0" role="button" aria-label="Inspect ${esc(p.name)}" class="${p.index===state.selected?'selected':''}"><td class="mono">${esc(p.name)}</td><td>${esc(p.readout)}</td><td class="right">${num(tval(p))} ${tmOk(p)?'':'*'}</td><td class="right">${num(p.gc_percent,1)}</td><td class="right">${countHere(p.index,state.region)}</td><td class="right">${q.off_target_review_count?qcTag(q.off_target_review_count+' flag(s)','review'):qcTag('0 local flags')}</td><td class="right">${q.max_dimer_stem} bp</td><td class="right">${q.spacing_flags.length?qcTag(q.spacing_flags.length,'review'):'0'}</td></tr>`;}).join('')||'<tr><td colspan="8" class="empty">No probes match this view. This is a scoped filter, not a full validation result.</td></tr>';}
function highlightQc(){for(const g of document.querySelectorAll('g.probe-site[data-hit]')){const h=DATA.hits[Number(g.dataset.hit)],p=DATA.probes[h.probe_index];g.style.opacity=qstate.dim&&!matchesQc(p)?.17:1;if(qstate.color==='readout')continue;let flagged=false;switch(qstate.color){case 'tm':flagged=!tmOk(p);break;case 'off':flagged=p.qc.off_target_review_count>0;break;case 'stem':flagged=stemFlag(p);break;case 'spacing':flagged=p.qc.spacing_flags.length>0;break;}for(const rect of g.querySelectorAll('rect')){if(rect.getAttribute('fill')==='#fff2cc'||(rect.getAttribute('fill')||'').startsWith('url'))continue;rect.setAttribute('fill',flagged?'#b16c13':'#728b97');}}}
function qcHeader(){const q=DATA.qc,c=q.counts,n=DATA.probes.length,inN=DATA.probes.filter(tmOk).length;
$('qcKpis').innerHTML=`<div class="qc-kpi"><strong>${inN} / ${n}</strong><span>${num(100*inN/n,1)}% inside selected Tm window</span></div><div class="qc-kpi"><strong>${c.local_offtarget_flagged_probes}</strong><span>probes with flags in searched references</span></div><div class="qc-kpi"><strong>${c.exact_pair_flags}</strong><span>pair comparisons with >=${q.settings.stem_review_length}-base exact stems</span></div><div class="qc-kpi"><strong>${c.flank_spacing_pairs}</strong><span>potential flank-spacing conflicts</span></div>`;
const prof=q.profiles[qstate.profile];$('qcSettings').textContent=`Arm Tm: ${q.settings.tm_low} < Tm < ${q.settings.tm_high} C; ${prof.nn_table}; Na ${prof.sodium_mM} mM; strands ${prof.higher_strand_nM}/${prof.lower_strand_nM} nM; formamide ${prof.formamide_percent}% x ${prof.formamide_factor} C/%. Whole-primary folding has separate settings. An asterisk in the table means outside this Tm window, not an experimentally failed probe.`;
$('qcMapLegend').textContent=qstate.color==='readout'?'Map colors identify the Dp7/Dp3 readout.':'Highlight mode: gold = flagged by the selected check; blue-grey = not flagged by that check. Neither color implies full validation.';
const fullRan=q.full_folding_scope.startsWith('RUN'),external=q.blast_runs.length>0;
$('qcCompletion').textContent='Scoped audit / not full validation';
$('qcScope').innerHTML=`<strong>Scope matters.</strong><p>${external?'External alignments are included; verify the listed database and run provenance.':'Human-genome screening: NOT RUN. No genome reference is embedded in this file.'} ${q.checks.find(x=>x.name==='Additional DNA references').status==='NOT_PROVIDED'?'Complete construct: NOT PROVIDED.':''}</p><p>${fullRan?'Full DNA folding ran in an aqueous model, without formamide or whole-pool equilibrium.':'Full folding: NOT RUN. Exact complementary-stem geometry was checked across complete primaries; this is not a full hairpin/dimer calculation.'} All ${n} input probes are retained.</p>`;
$('qcStatus').innerHTML=q.checks.map(x=>`<div class="qc-status-item"><strong>${esc(x.name)}</strong> ${qcTag(x.status,x.status==='RUN'?'ok':'pending')}<div class="qc-note">${esc(x.detail)}</div></div>`).join('');
$('qcRefs').textContent='Reference sequences actually searched: '+q.sources.map(r=>`${r.id} (${fmt(r.length)} bases; ${r.label})`).join('; ')+'. Database runs/imports: '+(q.blast_runs.map(b=>b.label+' ['+b.status+']').join('; ')||'none')+'.';}
function qcInspector(p){const q=p.qc;
let s=`<section class="qc-inspector"><h3>QC for this primary</h3><div class="facts"><div>Selected-model arm Tm<strong>${num(tval(p))} C</strong></div><div>Temperature window<strong>${tmOk(p)?'Within range':'Outside range'}</strong></div></div><p class="qc-note">${esc(profileLabels[qstate.profile]||qstate.profile)}. Temperature compliance is not a specificity or performance pass.</p>`;
s+=`<details><summary>Compare all three Tm models</summary><table class="qc-mini-table"><tbody>${Object.entries(q.thermo).map(([name,t])=>`<tr><td>${esc(profileLabels[name]||name)}</td><td>${num(t.adjusted_screen_C)} C</td><td>${t.in_window?'Within':'Outside'}</td></tr>`).join('')}</tbody></table></details>`;
const flags=q.off_targets.filter(h=>h.review!==false);
s+=`<details ${flags.length?'open':''}><summary>Off-target matches: ${flags.length} flags in searched references</summary><p class="qc-note">${flags.length?'Potential sequence matches outside the allowed target intervals. They are not predictions of occupied sites.':'No hits triggered the implemented local rules. Missing genome/construct references are not a specificity pass.'} Allowed repeats inside the assigned target region are not counted as off-targets.</p>`;
if(flags.length)s+=`<div class="qc-detail-scroll"><table class="qc-mini-table"><thead><tr><th>Reference / site</th><th>Match</th></tr></thead><tbody>${flags.slice(0,100).map(h=>`<tr><td>${esc(h.reference)}:${h.start}-${h.end}<br>${esc(h.source)} / binds ${esc(h.bound_strand)}</td><td>${h.alignment_length} nt; ${num(h.identity,1)}% identity<br>${h.mismatches} mismatches; ${esc(h.kind)}${h.qseq?'<br><span class="mono">'+esc(h.qseq)+'</span>':''}</td></tr>`).join('')}</tbody></table></div><p class="qc-note">Showing up to 100; all hits remain in JSON/CSV.</p>`;s+='</details>';
const stems=q.hairpin_stems;
s+=`<details><summary>Self-fold geometry: longest exact stem ${q.max_hairpin_stem} bases</summary><p class="qc-note">Full-primary sequence searched for complementary arms separated by at least ${DATA.qc.settings.hairpin_min_loop} bases. Length is a review flag, not a hairpin melting temperature. Bulges, mismatches and multiple stems are absent from this limited check.</p>`;
if(stems.length){const h=stems[0],seq=p.full||p.arm;const dot=Array.from({length:seq.length},()=>'.');for(let i=h.a_start-1;i<h.a_end;i++)dot[i]='(';for(let i=h.b_start-1;i<h.b_end;i++)dot[i]=')';s+=`<div class="qc-pair-geometry">${esc(seq)}\n${esc(dot.join(''))}</div><p class="qc-note">Example exact stem: primary positions ${h.a_start}-${h.a_end} paired with ${h.b_start}-${h.b_end}; ${h.loop_bases}-base loop. The symbols show sequence complementarity, not a predicted minimum-energy structure.</p>`;}s+='</details>';
const ps=q.partners.slice(0,8);
s+=`<details ${stemFlag(p)?'open':''}><summary>Probe-pair screen: longest exact stem ${q.max_dimer_stem} bases</summary><p class="qc-note">${fmt(DATA.qc.counts.exact_pair_comparisons)} homo/hetero combinations examined. The ${DATA.qc.settings.stem_review_length}-base review threshold is a configurable heuristic. These are not confirmed stable dimers.</p>${ps.map(r=>`<div class="qc-partner"><span class="mono">${esc(r.partner_name)}</span><strong>${r.max_stem} bp</strong><button data-qc-pair="${r.pair_index}">Show pairing</button><button data-probe="${r.partner_index}">Inspect probe</button></div>`).join('')}<div id="qcPairDetail"></div></details>`;
s+=`<details><summary>Full folding backend: ${esc(q.full_fold_status)}</summary>`;
if(q.full_fold){const f=q.full_fold;s+=`<p class="qc-note">${esc(f.engine)} / DNA Mathews 2004 / ${DATA.qc.settings.folding_temperature} C / ${DATA.qc.settings.sodium_M} M sodium / NO formamide correction.</p><p class="qc-note">Monomer minimum free energy: ${num(f.mfe_kcal_mol)} kcal/mol. Mean arm unpaired probability: ${num(f.mean_arm_unpaired,3)} in this aqueous model; not an in-cell binding probability.</p><pre>${esc(p.full||p.arm)}\n${esc(f.structure)}</pre>`;}else{s+='<p class="qc-note qc-missing">NOT RUN: the folding engine was not available for this saved result. Install ViennaRNA and rerun with --folding vienna. The primary was not truncated to fit a short-primer checker.</p>';}s+='</details>';
s+=`<details ${q.spacing_flags.length?'open':''}><summary>Flank-spacing check: ${q.spacing_flags.length} site-pair flags</summary><p class="qc-note">TT spacers and docking bases can sometimes extend a perfect target match. Extended gaps are sequence-based possibilities, not observed pairing. Negative gaps represent competing extensions, not simultaneous occupancy.</p>${q.spacing_flags.map(f=>`<div class="qc-note"><button data-inspect-hit="${f.site_id}">${esc(f.reference)}:${f.start}</button> with ${esc(f.partner_name)}: arm gap ${f.arm_gap} bp; potential extended gap <strong>${f.potential_gap} bp</strong>.</div>`).join('')}</details></section>`;return s;}
function showPair(index){const pair=DATA.qc.pair_interactions[index],a=DATA.probes[pair.a_index],b=DATA.probes[pair.b_index],x=pair.best_segment;if(!x)return;const sa=(a.full||a.arm).slice(x.a_start-1,x.a_end),sb=(b.full||b.arm).slice(x.b_start-1,x.b_end).split('').reverse().join('');let s=`<p class="qc-note">${esc(a.name)} ${x.a_start}-${x.a_end} paired antiparallel with ${esc(b.name)} ${x.b_start}-${x.b_end}.</p><div class="qc-pair-geometry">A 5' ${esc(sa)} 3'\n     ${'|'.repeat(x.length)}\nB 3' ${esc(sb)} 5'</div><p class="qc-note">Isolated matched-segment duplex Tm proxy: ${num(x.isolated_duplex_Tm_proxy_C)} C (DNA_NN3, 2/2 nM, 390 mM Na, 50% formamide approximation). This excludes tails and competing folds and is NOT the whole-primary dimer Tm.</p>`;if(pair.full_cofold){const f=pair.full_cofold;s+=`<p class="qc-note">Aqueous full cofold minimum-energy gain relative to separate folded strands: ${num(f.mfe_gain_vs_separate_kcal_mol)} kcal/mol. Not a concentration-corrected binding fraction.</p><pre>${esc(f.structure)}</pre>`;}$('qcPairDetail').innerHTML=s;}
const originalRenderInspector=renderInspector;
renderInspector=function(){originalRenderInspector();if(state.selected===null)return;const content=$('inspectorContent'),title=content.querySelector('h2');title.insertAdjacentHTML('afterend',qcInspector(DATA.probes[state.selected]));};
renderTable=qcTable;
renderAll=function(){renderOverview();renderControls();renderTable();renderInspector();qcHeader();highlightQc();};
function setupQc(){qstate.profile=DATA.qc.active_profile;$('qcProfile').innerHTML=Object.keys(DATA.qc.profiles).map(p=>`<option value="${esc(p)}">${esc(profileLabels[p]||p)}</option>`).join('');$('qcProfile').value=qstate.profile;}
$('qcProfile').addEventListener('change',()=>{qstate.profile=$('qcProfile').value;renderAll();});
$('qcFilter').addEventListener('change',()=>{qstate.filter=$('qcFilter').value;renderTable();highlightQc();});
$('qcSort').addEventListener('change',()=>{qstate.sort=$('qcSort').value;renderTable();});
$('qcColor').addEventListener('change',()=>{qstate.color=$('qcColor').value;renderAll();});
$('qcDim').addEventListener('change',()=>{qstate.dim=$('qcDim').checked;highlightQc();});
// The earlier listeners hold the original function object. Run the QC table last.
for(const id of ['searchInput','readoutFilter','repeatsOnly'])$(id).addEventListener(id==='searchInput'?'input':'change',()=>{renderTable();highlightQc();});
$('exportQc').addEventListener('click',()=>{const rows=visibleProbes().map(p=>[p.name,p.readout,p.expected_region,p.arm,p.full,qstate.profile,tval(p),tmOk(p),p.gc_percent,p.qc.off_target_review_count,p.qc.max_hairpin_stem,p.qc.max_dimer_stem,p.qc.full_fold_status,p.qc.spacing_flags.length]);const headers=['Probe','Readout','Region','Arm_5to3','Full_primary_5to3','Tm_profile','Tm_C','Tm_in_window','GC_percent','Off_target_review_hits','Max_hairpin_exact_stem','Max_pair_exact_stem','Full_fold_status','Flank_spacing_flags'];download('visible_probe_QC_NOT_AN_ORDER_FILE.csv',[headers,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n')+'\r\n','text/csv;charset=utf-8');});
$('loadQc').addEventListener('click',()=>$('qcFile').click());
$('qcFile').addEventListener('change',async()=>{try{const file=$('qcFile').files[0];if(!file)return;if(file.size>80*1024*1024)throw Error('Result JSON exceeds 80 MB viewer limit.');const next=JSON.parse(await file.text());if(!next.qc||next.qc.version!=='2.0.0'||!Array.isArray(next.probes)||!next.probes.length||!next.references?.length||!Array.isArray(next.hits))throw Error('Load binding_map.json from this integrated run_qc.py (version 2.0.0).');for(const p of next.probes)if(!p.qc?.thermo||p.index<0||p.index>=next.probes.length)throw Error('Malformed probe result.');for(const h of next.hits)if(!Number.isInteger(h.probe_index)||!next.probes[h.probe_index]||h.start<1||h.end<h.start)throw Error('Malformed site result.');for(const k of Object.keys(DATA))delete DATA[k];Object.assign(DATA,next);refs.clear();for(const r of DATA.references)refs.set(r.id,r);state.region=DATA.references[0].id;state.start=1;state.end=DATA.references[0].length;state.selected=DATA.hits.length?DATA.hits[0].probe_index:0;state.selectedHit=DATA.hits.length?DATA.hits[0].id:null;qstate.filter='all';qstate.sort='position';qstate.color='readout';$('qcFilter').value='all';$('qcSort').value='position';$('qcColor').value='readout';$('searchInput').value='';$('repeatsOnly').checked=false;setupQc();$('readoutFilter').innerHTML='<option value="">All readouts</option>'+[...new Set(DATA.probes.map(p=>p.readout))].map(r=>`<option value="${esc(r)}">${esc(r)}</option>`).join('');$('badges').innerHTML=`<span class="badge">${DATA.probes.length} oligos</span><span class="badge">${DATA.hits.length} exact sites</span><span class="badge">Input sequences unchanged</span>`;$('strandBanner').textContent=DATA.hits.length&&DATA.hits.every(h=>h.bound_strand==='-')?'These probes bind the BOTTOM (-) DNA strand.':'Both orientations are searched. Inspect each site for its bound strand.';$('qcLoadError').textContent='';$('warnings').textContent=(DATA.warnings||[]).join(' ');$('warnings').classList.toggle('hidden',!(DATA.warnings||[]).length);$('inputInfo').textContent='Loaded '+file.name+' / probe source '+DATA.probe_source_file;renderAll();}catch(e){$('qcLoadError').textContent='Cannot load result: '+e.message;}finally{$('qcFile').value='';}});
$('saveQcHtml').addEventListener('click',()=>{const clone=document.documentElement.cloneNode(true),d=JSON.parse(JSON.stringify(DATA));d.qc.active_profile=qstate.profile;clone.querySelector('#dataset').textContent=JSON.stringify(d).replace(/</g,'\\u003c').replace(/>/g,'\\u003e').replace(/&/g,'\\u0026');download('RASERFISH_QC_viewer.html','<!doctype html>\n'+clone.outerHTML,'text/html;charset=utf-8');});
$('openRunHelp').addEventListener('click',()=>{$('qcRunHelp').open=true;$('qcRunHelp').scrollIntoView({behavior:'smooth',block:'center'});});
document.addEventListener('click',e=>{const b=e.target.closest('[data-qc-pair]');if(b)showPair(Number(b.dataset.qcPair));});
setupQc();renderAll();
window.probeViewer.render=renderAll;
window.integratedQC={state:qstate,render:renderAll,visibleProbes,showPair};
'''


def render_qc_html(data: dict) -> str:
    page=HTML_TEMPLATE
    # Replace inaccurate arm-gap / total-validation wording inherited from old UI.
    page=page.replace('Primary probes / 5-base minimum gaps','Primary probes / integrated QC')
    page=page.replace('RASER-FISH / SEQUENCE MAP','RASER-FISH / MAP + QUALITY REVIEW')
    page=page.replace('Explore the redesigned DP7 and DP3 pools. Every exact repeat copy is included in the spacing check. Click a site to inspect its binding arm, target strand and all repeated copies.',
       'Inspect the current Dp7 and Dp3 probes alongside their temperature estimates, scoped off-target checks, complementary-stem flags and spacing caveats. No oligos are changed or removed.')
    page=page.replace(' unoccupied DNA bases',' bases between defined arms').replace(' unoccupied bases:',' bases between defined arms:')
    page=page.replace('Grey = non-targeting flanks','Grey = designated flanks (possible target extensions are separately checked)')
    page=page.replace('No mismatches, short partial matches, circular-junction sites, RNA annotations, or genome-wide off-targets are included.',
        'The binding maps show exact arm matches only. Additional QC layers have separate scope labels above. Circular junctions and missing references are not inferred.')
    page=page.replace('All mapped copies: ${r.summary.spacing_pairs_checked} neighbor pairs checked; minimum gap',
        'Defined arms: ${r.summary.spacing_pairs_checked} neighbor pairs checked; minimum arm gap')
    page=page.replace('${DATA.required_min_gap_nt}-base gaps: ${DATA.spacing_all_pass?\'PASS\':\'CHECK\'}',
        '${DATA.required_min_gap_nt}-base ARM gaps: ${DATA.spacing_all_pass?\'met\':\'check\'}')
    page=page.replace('<div id="warnings" class="notice hidden"></div>',QC_HEADER+'\n<div id="warnings" class="notice hidden"></div>')
    page=page.replace('<p class="range-info">One row per oligo. Filters apply to this list; maps continue to show every site.</p>',QC_FILTER)
    page=page.replace('<th class="right">Arm nt</th><th class="right">GC %</th><th class="right">Sites</th><th>Positions (inclusive)</th>',
        '<th class="right">Tm (C)</th><th class="right">GC %</th><th class="right">Sites</th><th>Off-targets</th><th>Pair stem</th><th>Flank flags</th>')
    page=page.replace('</style>',QC_CSS+'\n</style>',1)
    page=page.replace('</script>\n</body>',QC_JS+'\n</script>\n</body>',1)
    safe=json.dumps(data,ensure_ascii=True,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    return page.replace('__PAGE_TITLE__',html.escape(data['title'])).replace('__DATA_JSON__',safe)
